/**
 * @summary Attach a worker document
 */
export const attachWorkerDocument = (
	workerId: string,
	attachWorkerDocumentBody: BodyType<AttachWorkerDocumentBody>,
	options?: SecondParameter<typeof customInstance>,
	signal?: AbortSignal,
) => {
	const formData = new FormData();
	if (attachWorkerDocumentBody.file !== undefined) {
		formData.append(`file`, attachWorkerDocumentBody.file);
	}

	if (attachWorkerDocumentBody.category !== undefined) {
		formData.append(`category`, attachWorkerDocumentBody.category);
	}

	if (attachWorkerDocumentBody.documentDate !== undefined) {
		formData.append(`documentDate`, attachWorkerDocumentBody.documentDate);
	}

	if (attachWorkerDocumentBody.validUntil !== undefined) {
		formData.append(`validUntil`, attachWorkerDocumentBody.validUntil);
	}

	if (attachWorkerDocumentBody.note !== undefined) {
		formData.append(`note`, attachWorkerDocumentBody.note);
	}

	return customInstance<WorkerDocumentAttached>(
		{
			url: `/api/workers/${workerId}/documents`,
			method: "POST",
			headers: { "Content-Type": "multipart/form-data" },
			data: formData,
			signal,
		},
		options,
	);
};

